  installWebGLInstanceMethods(runtime);
  jsi::Object gl = ctx->supportsWebGL2
                   ? createWebGLObject(
      runtime, SKWebGLClass::WebGL2RenderingContext, {static_cast<double>(ctx->ctxId)})
                     .asObject(runtime)
                   : createWebGLObject(
      runtime, SKWebGLClass::WebGLRenderingContext, {static_cast<double>(ctx->ctxId)})
                     .asObject(runtime);

  (void)viewport;  // ScreenKit: drawingBufferWidth/Height are getter-only accessors on
  // the prototypes, reading the live surface (gfx/VendoredWebGL.cpp). A snapshot here
  // would go stale on a resize, and -- once a second canvas has installed the accessors
  // -- writing one would throw against them.
  gl.setProperty(runtime, "supportsWebGL2", ctx->supportsWebGL2);
  gl.setProperty(runtime, "contextId", static_cast<double>(ctx->ctxId));

